package app.flare.auto;
import android.app.*;import android.os.*;import android.content.*;import android.text.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.util.*;import org.json.*;

public final class IconPickerActivity extends Activity {
 UiKit ui;final ArrayList<Item> all=new ArrayList<>(),visible=new ArrayList<>();final Handler main=new Handler(Looper.getMainLooper());BaseAdapter adapter;String pkg;
 static final class Item{final String name,res;Item(String n,String r){name=n;res=r;}}
 @Override public void onCreate(Bundle b){super.onCreate(b);ui=new UiKit(this);getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(ui.t.background));getWindow().getDecorView().setSystemUiVisibility(UiFlags.IMMERSIVE);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);pkg=getIntent().getStringExtra("package");if(pkg==null||pkg.isEmpty()){finish();return;}LinearLayout root=ui.column();root.setFocusableInTouchMode(true);root.setBackgroundColor(ui.t.background);root.addView(ui.header("Choose an icon"),new LinearLayout.LayoutParams(-1,ui.dp(56)));EditText search=new EditText(this);search.setSingleLine(true);search.setHint("Search icons");search.setTextSize(16);search.setTextColor(ui.t.textPrimary);search.setHintTextColor(ui.t.textSecondary);search.setMinHeight(ui.dp(56));root.addView(search);ListView list=new ListView(this);list.setDivider(null);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.requestFocus();adapter=new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int n){return visible.get(n);}public long getItemId(int n){return n;}public View getView(int n,View recycled,ViewGroup parent){LinearLayout row;if(recycled instanceof LinearLayout)row=(LinearLayout)recycled;else{row=new LinearLayout(IconPickerActivity.this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(ui.dp(16),0,ui.dp(16),0);row.setMinimumHeight(ui.dp(56));ImageView icon=new ImageView(IconPickerActivity.this);icon.setId(android.R.id.icon);row.addView(icon,new LinearLayout.LayoutParams(ui.dp(36),ui.dp(36)));TextView name=ui.text("",16,ui.t.textPrimary);name.setId(android.R.id.text1);name.setPadding(ui.dp(16),0,0,0);row.addView(name,new LinearLayout.LayoutParams(0,ui.dp(56),1));}Item item=visible.get(n);ImageView icon=row.findViewById(android.R.id.icon);try{int id=getResources().getIdentifier(item.res,"drawable",getPackageName());icon.setImageResource(id);icon.setColorFilter(ui.t.textPrimary);}catch(RuntimeException e){icon.setImageDrawable(null);}((TextView)row.findViewById(android.R.id.text1)).setText(item.name);return row;}};list.setAdapter(adapter);list.setOnItemClickListener((p,v,n,id)->chooseColor(visible.get(n)));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){filter(s.toString());}public void afterTextChanged(Editable e){}});new Thread(()->{try(java.io.InputStream in=getAssets().open("simple-icons-picker.json");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] buf=new byte[8192];for(int n;(n=in.read(buf))!=-1;)out.write(buf,0,n);JSONArray data=new JSONArray(out.toString("UTF-8"));ArrayList<Item> result=new ArrayList<>();for(int i=0;i<data.length();i++){JSONObject o=data.getJSONObject(i);result.add(new Item(o.getString("name"),o.getString("resource")));}main.post(()->{if(isFinishing()||isDestroyed())return;all.addAll(result);filter(search.getText().toString());});}catch(Exception ignored){main.post(()->Toast.makeText(this,"Icon catalog unavailable",Toast.LENGTH_SHORT).show());}}).start();}
 void chooseColor(Item item){String[] names={"Theme color","White","Red","Orange","Yellow","Green","Cyan","Blue","Purple","Pink","Custom color"};int[] colors={ui.t.textPrimary,0xffffffff,0xffef5350,0xffffa040,0xffffd15c,0xff4cce85,0xff37cdd4,0xff59aaff,0xffbd89ff,0xffff80b5};new ThemedDialogs.Builder(this).setTitle("Icon color").setItems(names,(dialog,n)->{if(n==10){customColor(item);return;}save(item,n==0?null:Integer.valueOf(colors[n]));}).show();}
 void customColor(Item item){EditText input=new EditText(this);input.setSingleLine(true);input.setHint("#RRGGBB");new ThemedDialogs.Builder(this).setTitle("Custom icon color").setView(input).setPositiveButton("Save",(dialog,n)->{String raw=input.getText().toString().trim();try{if(!raw.matches("#[0-9a-fA-F]{6}"))throw new IllegalArgumentException();save(item,android.graphics.Color.parseColor(raw));}catch(Exception e){Toast.makeText(this,"Enter a color like #E60012",Toast.LENGTH_LONG).show();}}).setNegativeButton("Cancel",null).show();}
 void save(Item item,Integer color){SharedPreferences.Editor edit=getSharedPreferences("home",0).edit().putString("icon_override_"+pkg,item.res).remove("icon_image_"+pkg);if(color==null)edit.remove("icon_color_"+pkg);else edit.putInt("icon_color_"+pkg,color);edit.apply();setResult(RESULT_OK,new Intent().putExtra("package",pkg).putExtra("icon",item.res));finish();}
 void filter(String query){String q=query.toLowerCase(Locale.ROOT).trim();visible.clear();for(Item i:all)if(i.name.toLowerCase(Locale.ROOT).contains(q))visible.add(i);adapter.notifyDataSetChanged();}
 @Override protected void onDestroy(){main.removeCallbacksAndMessages(null);super.onDestroy();}
}
